"""AC-003 / NFR-003 gate: layering invariant across member pyprojects.

packages/* may depend only on packages/*; verticals may depend on packages +
sibling verticals; apps may depend on anything. Exit 0 = clean.
"""

from __future__ import annotations

import sys
import tomllib
from pathlib import Path

ROOT = Path(__file__).resolve()
while not (ROOT / "pyproject.toml").exists() or ROOT == ROOT.parent:
    ROOT = ROOT.parent

VERTICAL_PREFIXES = ("hh-",)
APP_NAMES = {"home-health-scribe"}


def base_name(dep: str) -> str:
    for sep in (">", "<", "=", "[", " ", "!"):
        dep = dep.split(sep)[0]
    return dep.strip()


def main() -> int:
    violations: list[str] = []
    for layer_glob, layer in (("packages/*", "package"), ("verticals/home-health/*", "vertical")):
        for member in sorted(ROOT.glob(layer_glob)):
            pp = member / "pyproject.toml"
            if not pp.exists():
                continue
            deps = tomllib.loads(pp.read_text())["project"].get("dependencies", [])
            for dep in map(base_name, deps):
                if dep in APP_NAMES:
                    violations.append(f"{member.name} ({layer}) -> app {dep}")
                elif layer == "package" and dep.startswith(VERTICAL_PREFIXES):
                    violations.append(f"{member.name} (package) -> vertical {dep}")
    for v in violations:
        print(f"LAYERING VIOLATION: {v}", file=sys.stderr)
    return 1 if violations else 0


if __name__ == "__main__":
    sys.exit(main())

"""Target workspace map model — `reference/target-map.json` validates against this.

Design contract only (create-time reviewer floor, SK-0008); not shipped code.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Literal

Layer = Literal["packages", "verticals/home-health", "apps"]
Depth = Literal["DEEP", "MIN", "SKEL", "COMPOSED"]


@dataclass(frozen=True)
class Member:
    name: str
    layer: Layer
    absorbs: list[str] = field(default_factory=list)
    deps: list[str] = field(default_factory=list)
    depth: Depth = "SKEL"


@dataclass(frozen=True)
class TargetMap:
    members: list[Member]

    def __post_init__(self) -> None:
        if len(self.members) != 8:
            raise ValueError(f"target map must have exactly 8 members, got {len(self.members)}")


def load(path: str) -> TargetMap:
    """Parse + validate a target-map JSON file."""
    import json

    raw = json.load(open(path))
    return TargetMap(members=[Member(**m) for m in raw["members"]])


if __name__ == "__main__":
    import sys

    load(sys.argv[1] if len(sys.argv) > 1 else "target-map.json")
    print("ok")

"""AC-006 / FR-007 gate: commitlint scope-enum matches post-trim members and
every x-scope-patterns glob resolves to an existing path. Exit 0 = clean.

Stdlib-only YAML extraction (the config is data-only; no yaml dep in workspace).
"""

from __future__ import annotations

import re
import sys
from glob import glob
from pathlib import Path

ROOT = Path(__file__).resolve()
while not (ROOT / ".commitlintrc.yaml").exists() or ROOT == ROOT.parent:
    ROOT = ROOT.parent

STATIC = {"workspace", "packages", "verticals", "apps", "docs", "ci", "deps",
          "infra", "vault", "adr", "spec", "research"}
MEMBERS = {"hdp-core", "hdp-api", "hdp-agent", "hdp-observability", "hdp-hitl",
           "hh-scribe", "hh-emr-sync", "home-health-scribe"}


def main() -> int:
    text = (ROOT / ".commitlintrc.yaml").read_text()
    enum_block = re.search(r"scope-enum:.*?\[(.*?)\]", text, re.S)
    if not enum_block:
        print("scope-enum block not found", file=sys.stderr)
        return 1
    scopes = {s.strip().rstrip(",") for s in enum_block.group(1).split(",") if s.strip()}
    expected = STATIC | MEMBERS
    errors = []
    if scopes != expected:
        extra, missing = scopes - expected, expected - scopes
        if extra:
            errors.append(f"unexpected scopes: {sorted(extra)}")
        if missing:
            errors.append(f"missing scopes: {sorted(missing)}")
    for m in re.finditer(r'^\s+(?:- )?"?([\w./*-]+/\*\*)"?\s*$', text, re.M):
        pattern = m.group(1)
        if not glob(str(ROOT / pattern.replace("/**", ""))):
            errors.append(f"x-scope-patterns glob resolves to nothing: {pattern}")
    for e in errors:
        print(f"COMMITLINT MISMATCH: {e}", file=sys.stderr)
    return 1 if errors else 0


if __name__ == "__main__":
    sys.exit(main())

